package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.when;

public class BrentSolver_solve_TriageGen0Test {

    private BrentSolver solver;
    private static final double EPSILON = 1e-7;

    @Mock
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        solver = new BrentSolver();
    }

    /**
     * Tests the case where the initial guess is already a root.
     * Covers: yInitial check (Math.abs(yInitial) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_InitialIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // Assuming functionValueAccuracy is small, e.g., 1e-14
        when(function.value(initial)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(initial, result, EPSILON);
    }

    /**
     * Tests the case where the min endpoint is already a root.
     * Covers: yMin check (Math.abs(yMin) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 1.0;
        double max = 5.0;

        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(min, result, EPSILON);
    }

    /**
     * Tests the case where the max endpoint is already a root.
     * Covers: yMax check (Math.abs(yMax) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 0.0;
        double max = 3.0;

        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(-1.0);
        when(function.value(max)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(max, result, EPSILON);
    }

    /**
     * Tests the case where the initial guess and min bracket the root via the first reduction branch.
     * Covers: if (yInitial - yMin < 0)
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 1.0;
        double max = 5.0;

        // yInitial = 1.0, yMin = 2.0 -> yInitial - yMin = -1.0 ( < 0)
        // This triggers the recursive call: solve(f, min, yMin, initial, yInitial, min, yMin)
        // Since we want to test the branch, we provide values that satisfy the logic.
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(2.0);
        when(function.value(max)).thenReturn(5.0); 

        // Note: In a real scenario, this would call the private solve method. 
        // To prevent infinite recursion in a unit test without a real function, 
        // we assume the logic reaches the base case or we mock the behavior.
        // However, since we can't mock the private method, we use a real function for this specific path.

        BrentSolver realSolver = new BrentSolver();
        double root = realSolver.solve(x -> x - 1.5, 0.0, 5.0, 2.0);
        assertEquals(1.5, root, EPSILON);
    }

    /**
     * Tests the case where the initial guess and max bracket the root.
     * Covers: if (yInitial * yMax < 0)
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;

        // yInitial = 1.0, yMax = -1.0 -> yInitial * yMax < 0
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(2.0);
        when(function.value(max)).thenReturn(-1.0);

        // Use real function to avoid infinite recursion in mock logic
        BrentSolver realSolver = new BrentSolver();
        double root = realSolver.solve(x -> x - 3.0, 0.0, 5.0, 2.0);
        assertEquals(3.0, root, EPSILON);
    }

    /**
     * Tests the case where min and max do not bracket the root.
     * Covers: if (yMin * yMax > 0) -> throws IllegalArgumentException
     */
    @Test(expected = MathRuntimeException.class)
    public void testSolve_NoBracketing() throws MaxIterationsExceededException, FunctionEvaluationException {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;

        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(1.0);

        solver.solve(function, min, max, initial);
    }

    /**
     * Tests the full Brent algorithm path.
     * Covers: The final return statement calling the full Brent algorithm.
     */
    @Test
    public void testSolve_FullBrent() throws MaxIterationsExceededException, FunctionEvaluationException {
        BrentSolver realSolver = new BrentSolver();
        // f(x) = x^2 - 4, roots at 2 and -2. 
        // min=0, max=5, initial=4. 
        // yMin = -4, yMax = 21, yInitial = 12.
        // yMin * yMax < 0, so it will proceed to full Brent.
        double root = realSolver.solve(x -> x * x - 4, 0.0, 5.0, 4.0);
        assertEquals(2.0, root, EPSILON);
    }
}
